# DK LOP.  Lersøen - Østerport
#
let lo = path("d3.dk.lop");

with detail = 4, railway = :first :museum {
    # point.dk.Lersøen  dk.VLH

    with link = "line.dk.LOP" {
        track(:lor,
                lo[:ler.yh + 0.9dl, :ler.yh + 1dl] >> 1.5mo
            ..  lo[:ryp.yf, :ryp - 0.49sw] >> 3.5mo
        );
        track(:lor :station, lo[:ryp - 0.5sw, :ryp + 0.5sw] >> 3.5mo);
        track(:lor,
                lo[:ryp + 0.49sw, :ryp + 0.5sw] >> 3.5mo
            ..  lo[:ryp.xs, :ryp.xs + 0.1dl] >> 1.5mo
        );
        track(:lor, lo[:ryp.xs, :sva.xf - 5mo] >> 1.5mo);
        track(:lor,
                lo[:sva.xf - 5.1mo, :sva.xf - 5mo] >> 1.5mo
            ..  lo[:sva.yf, :sva.yf + 0.1dl] >> 5.5mo
        );
    }

    # point.dk.Svanemøllen  dk.KKB

    with link = "line.dk.LOP" {
        track(:lor, lo[:sva + 400m, :heg - 0.49sw] >> 3.5mo);
        track(:lor, lo[:heg - 0.5sw, :heg + 80m] >> 3.5mo);
        track(:lor,
                lo[:heg + 79m, :heg + 80m] >> 3.5mo
            ..  lo[:nha - 351m, :nha - 350m] >> 4.5mo
        );
        with layer = -1 track(
                lo[:nha - 351m, :nha - 350m] >> 4.5mo
            ..  lo[:nha - 80m, :nha - 79m] << 2.5mo
        );
        track(:ror,
                lo[:nha - 80m, :nha - 79m] << 2.5mo
            ..  lo[:nha + 249m, :nha + 250m] << 1.5mo
        );
        track(:ror, lo[:nha + 249m, :ost - 749m] << 1.5mo);
    }
}


